-- aar/w3/aar_row_634_draft1.sql. DRAFT 1 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3.
-- One ask_aar_snapshots row for ASK 634 (a judge's corrected FORCED line is applied at its pair's FORCED line) and its ask_aar_builders row.
-- Every value is from Wall 12002, 12009, 12043, 12046, 12069, 12075, 12076, 12077, 12078, 12082, 12085, 12121, 12128 and 12129, ask634/w4/plan634.md rev 0 (head read by W3; the plan was read whole before the manual entry) (each read whole by W3), W4's facts file aar/w3/cards_641_to_652_from_w4.md (md5 380e6b134460a413f6f57ea766452fc7), and md5sum by W3 of the files named.
-- NOT READ by W3: the card and the press in W4's thread (taken from W4's facts file); the audit_log row; the live engine and n8n; W1's grade files in git; Wall 12001 and 12008 (W4's plan and build b1 posts).
-- objective_met is 'in part': written and read back; no run since the write.
-- After the insert: SELECT * FROM ask_aar_snapshots_check(); SELECT * FROM ask_aar_grades_check();
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (634, '0', $t$ASK 634: a judge's corrected FORCED line is applied at that pair's FORCED line when the line it flagged is not in its text$t$,
  $t$In run 42528 sol's send-back changes S9, S10 and S14 flagged a line that is sol's own pointer and was never in sol's judgment text, so the apply refused each one ("the flagged line is not in the judge text", NOT APPLIED). At the gate (G2, G3, G7) sol answered each with CHANGE TO and a whole FORCED line for the same pair, and the re-apply anchored on the same missing line and failed again; the items stayed UNCURED and counted in drv_uncured, and no CHANGE TO could have cured them (enforcer rows 54568, 54569, 54573). Change, Shared Library sbApply2024 (LIB 1426): when the flagged line is not found and the change is a FORCED line for a named pair, it is applied at the one FORCED line of that pair in the judge's text; with no such line, or more than one, it stays NOT APPLIED as before. This is the rule the engine already uses for a RETRACTED change. Expected effect on 42528: G2, G3 and G7 would be applied and CURED, sol's drv_uncured 9 to 6, the outcome unchanged. Not changed: reasoning, a model setting, a prompt, a count rule, what a judge is sent. (plan rev 0, heading 1, ask634/w4/plan634.md md5 4735a147)$t$,
  'in part',
  $t$Written by W4 on the operator's press "Write it" at 08:35 CST 2026-11-25 on W4's card (Wall 12082; audit 42241 by W4's facts file), engine e11a57aa to 7f4e5503, after W1's recheck PASS of the rebased target b4 e6d00811 (Wall 12078), and read back PASS by W1 (Wall 12085: live 7f4e5503 equals W1's b4 rebuild in all 426 nodes; t634 22 pass 0 fail; standing 31 PASS 0 FAIL). Shared Library only, one LIB line (1426); 13 MAP lengths re-measured; nothing was deleted. IN PART, because no run has been made since the write. This change moves items from UNCURED to CURED, which feeds drv_uncured and seat removal: W1's N1 on the plan (Wall 12002) asked for the effect on the verdict, and it is met (Wall 12009): sol's stored verdict_raw for 42528 has exactly one line-start FORCED line for each of D3 vs C4, D5 vs C2 and D6 vs C1; sol's drv_uncured goes from 9 to 6, sol stays unseated and the outcome does not change (NOT CHECKED by W1: the stored 9). The written target is the fourth rebase of one unchanged build script: the first build on 3b72583c (5309a11f, PASS, Wall 12009), b1 on ee4e389d (2136d5ad, checked, Wall 12046), b2 on the 641 fetch-back (7a19c8be; W4 found no W1 post naming it), b3 on the 645 fetch-back (56ea8c28, PASS, Wall 12076), b4 on the 646 fetch-back (e6d00811, PASS, Wall 12078); in each the one changed line is byte-equal to the graded text. NOT CHECKED by W1: enforcer rows 54568, 54569 and 54573 (plan grade); the audit row. Open: two clean live runs.$t$,
  '12002, 12009, 12043, 12046, 12069, 12075, 12076, 12077, 12078, 12082, 12085, 12121, 12128, 12129',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$W4's write card (cmsg_017ZQamDMHrS6fqMHnQDVo584otzyTAZs2oZpEscmXAHnW, "Write ASK 634 so a judge's corrected FORCED line is applied at its pair's line?"): he pressed "Write it" at 08:35 CST 2026-11-25. Card text, press and time are from W4's facts file; W3 did not read the card or the press. There was no build card: the build was offline files only, and the card came after the build grade.$t$::text),
  $j${"answer": "Write it", "question": "Write ASK 634 so a judge's corrected FORCED line is applied at its pair's line?", "options": {"Write it": "I change one line of the engine's shared library. In 42528, sol's three items would have counted as cured (uncured 9 to 6), with no change to the outcome. W1 reads it back.", "Hold": "The engine stays as it is. A judge that corrects a pointer line at the gate still cannot cure it, and the item counts against the judge."}, "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo584otzyTAZs2oZpEscmXAHnW", "press_time": "08:35 CST 2026-11-25", "message_above_the_card": "cmsg_017ZQamDMHrS6fqMHnQDVo582HTcBQvHEbeAAvhuJJA9sb", "source": "W4's facts file aar/w3/cards_641_to_652_from_w4.md; W3 did not read the card or the press. The card was posted at 06:16 CST."}$j$::jsonb,
  'W4',
  $j${"md5": "4735a147f96353c9f6366e3bc6b6f042", "path": "ask634/w4/plan634.md", "note": "plan rev 0, graded PASS WITH N1 by W1 (Wall 12002); N1 met in the build (Wall 12009).", "source": "md5sum by W3; Wall 12002"}$j$::jsonb,
  $j$[{"path": "ask634/w4/b4/b634.cjs", "md5": "9e4de239870631b7e2ced53865ea76fe", "what": "build script (the same file in b1 to b4)"}, {"path": "ask634/w4/b4/tg/target_engine_634.json", "md5": "e6d008111e84aacc1880718fa39e3f75", "what": "target engine b4, on e11a57aa (written)"}, {"path": "ask634/w4/b3/tg/target_engine_634.json", "md5": "56ea8c2861270ef256ca18471739f8c0", "what": "target engine b3 (not written)"}, {"path": "ask634/w4/b2/tg/target_engine_634.json", "md5": "7a19c8be1c603e9bbd2e5432228827a5", "what": "target engine b2 (not written)"}, {"path": "ask634/w4/b1/tg/target_engine_634.json", "md5": "2136d5ad6fd06983e7b50d0dda04a224", "what": "target engine b1, on ee4e389d (not written)"}, {"path": "ask634/w4/b4/t634.cjs", "md5": "7a4fee2d2f9787ca429a2f2618afd7d9", "what": "test"}, {"path": "ask634/w4/b4/out_t634.txt", "md5": "22e230ecd7486654de306013f78d07f4", "what": "test output"}, {"path": "ask634/w4/write/write634.sh", "md5": "6eb56d01a4479a28cc7e92a0c22f48de", "what": "write script"}, {"path": "ask634/w4/write/fetchback_eng_634.json", "md5": "9eb6db1e82dde9644f033718b2616fcb", "what": "fetch-back after the write"}]$j$::jsonb,
  $j${"engine": "ask634/w4/write/revert_eng_634.json, md5 e40b088f16d5bbb74eaddb9a4c6dbc76 (restores e11a57aa)", "child": "not written; nothing to revert", "database": "not written; nothing to revert", "rehearsed": "not stated in the posts W3 read", "source": "Wall 12082; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1 (plan rev 0)", "wall_id": 12002, "md5_graded": "4735a147", "verdict_norm": "PASS", "source": "Wall 12002"}, {"seat": "W1", "verdict": "PASS (first build, on 3b72583c)", "wall_id": 12009, "md5_graded": "5309a11f", "verdict_norm": "PASS", "source": "Wall 12009"}, {"seat": "W1", "verdict": "CHECKED (rebase b1 on ee4e389d)", "wall_id": 12046, "md5_graded": "2136d5ad", "verdict_norm": "PASS", "source": "Wall 12046"}, {"seat": "W1", "verdict": "PASS (recheck of b3)", "wall_id": 12076, "md5_graded": "56ea8c28", "verdict_norm": "PASS", "source": "Wall 12076"}, {"seat": "W1", "verdict": "PASS (recheck of b4 on e11a57aa)", "wall_id": 12078, "md5_graded": "e6d008111e84aacc1880718fa39e3f75", "verdict_norm": "PASS", "source": "Wall 12078 (names e6d00811); full md5 by md5sum of the target"}]$j$::jsonb,
  ARRAY['e6d008111e84aacc1880718fa39e3f75'], '[42241]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN, node Shared Library (LIB 1426, sbApply2024)", "before": "version e11a57aa; a change whose flagged line is not in the judge text is NOT APPLIED unless it is \"RETRACTED: <pair>\"", "after": "version 7f4e5503-4e17-42df-a05b-882cbf04ac50; a FORCED change for a named pair is applied at the one FORCED line of that pair, else NOT APPLIED as before; 13 MAP lengths re-measured"}]$j$::jsonb,
  $j$[{"name": "t634.cjs on the build", "result": "22 pass, 0 fail, on every rebase", "source": "Wall 12009, 12043, 12046, 12076, 12078; on live, Wall 12085"}, {"name": "The 42528 case from the database", "result": "sol's stored verdict_raw has exactly one line-start FORCED line for each of D3 vs C4, D5 vs C2 and D6 vs C1; drv_uncured 9 to 6; sol stays unseated; outcome unchanged", "source": "W1, Wall 12009"}, {"name": "Standing set with child aad0ad9c", "result": "31 PASS, 0 FAIL on the target (W4, W1), on the fetch-back (W4, Wall 12082) and on live (W1, Wall 12085); pair Library Check PASSES; reg385 PASS", "source": "Wall 12077, 12078, 12082, 12085"}, {"name": "NOT RUN", "result": "any live call", "source": "Wall 12082"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "PASS (live 7f4e5503 equals W1's b4 rebuild in all 426 nodes; t634 22 pass 0 fail; standing 31 PASS 0 FAIL). NOT CHECKED: audit row.", "wall_id": 12085, "source": "Wall 12085 (commit 6a0a12e2)"}]$j$::jsonb,
  $j${"case": "NO RUN YET.", "runs": [], "mark_for_the_next_run": "on the first run in which a judge answers a gate item with CHANGE TO and a whole FORCED line whose flagged line is not in its text: the change is APPLIED at that pair's one FORCED line and the item is CURED; with none or more than one such line it reads NOT APPLIED as before.", "not_shown": "the rule on a live gate.", "source": "Wall 12082; plan634.md heading 1"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "WRITTEN: part 09.1 version 333 (md5 38c2ebc14b1127788728d1c60f388fdd, 47,479 characters, log row 353), on the operator's press \"Write all six\" at 09:08 CST 2026-11-25 on W3's card (cmsg_017ZQamDMHrS6fqMHnQDVo589AHY4EW5dD8Zdyt26PvafU); audit 42303; pairs graded PASS by W1 (Wall 12121); read back PASS by W1 (Wall 12129)."}$j$::jsonb,
  'read back', $j$[12002, 12009, 12043, 12046, 12069, 12075, 12076, 12077, 12078, 12082, 12085, 12121, 12128, 12129]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W4'], $j$[{"seat": "W4", "what": "planned, built (rebased four times) and wrote ASK 634 on the operator's card", "wall_id": 12082}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
